// The filter agrees with the Python, over the real table.
//
// `filter_all` is the one function every view runs on every filter change, and
// the port has to agree exactly -- not approximately, and not only on the
// cases I thought to write down. A row that should have dropped out and did
// not is a point drawn that the user filtered away, and nothing on screen
// flags it.
//
// `test/fixtures/filters.json` was generated by `scripts/filter_golden.py`
// against `data/NuScenes/scene_0061.parquet`: 51 cases, seeded, including the
// edge cases that are easy to get wrong. The table is read here through the
// real reader, so this also checks that the two agree about what the columns
// are before they can agree about which rows pass.
//
// The expected rows are a bitmask rather than a list of indices: the same
// information, exactly, at a sixteenth of the size in a file that is only ever
// compared whole.

import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import { beforeAll, describe, expect, it } from 'vitest'

import { readTable } from '../src/data/parquet'
import {
  buildTable,
  clampFrameIndex,
  filterAll,
  frameRows,
  rangeOf,
  visibleRows,
  type Column,
  type FilterState,
  type Table,
  type Visibility
} from '../src/shared/table'

interface Case {
  label: string
  numeric: Array<{ column: string; min: number; max: number }>
  categorical: Array<{ column: string; allowed: string[] }>
  visible: Visibility[] | null
  kept_count: number
  /** One bit per row, LSB first, base64. */
  kept_bits: string
}

interface Fixture {
  table: string
  rows: number
  hidden_every: number
  cases: Case[]
}

const fixture: Fixture = JSON.parse(
  readFileSync(join(__dirname, 'fixtures', 'filters.json'), 'utf8')
)

/** Unpack a base64 bitmask, LSB first, into a mask one byte per row. */
function unpackMask(bits: string, rows: number): Uint8Array {
  const packed = Buffer.from(bits, 'base64')
  const mask = new Uint8Array(rows)
  for (let row = 0; row < rows; row++) {
    mask[row] = (packed[row >> 3]! >> (row & 7)) & 1
  }
  return mask
}

let table: Table

beforeAll(() => {
  const root = join(__dirname, '..')
  const data = readTable(join(root, fixture.table))
  table = buildTable(data.rows, data.columns as Column[], 'Frame')

  // The same deterministic scatter the generator used.
  for (let row = 0; row < table.rows; row++) {
    table.visible[row] = row % fixture.hidden_every === 0 ? 1 : 0
  }
})

describe('the reader and the Python agree about the table', () => {
  it('reads the same number of rows', () => {
    expect(table.rows).toBe(fixture.rows)
  })

  it('builds a frame index covering every row', () => {
    // Every row belongs to exactly one frame, so the CSR arrays account for
    // all of them -- a row that falls out here would silently never be drawn.
    expect(table.frameStart[table.frameIds.length]).toBe(table.rows)
    expect(table.rowOrder.length).toBe(table.rows)
    expect(new Set(table.rowOrder).size).toBe(table.rows)
  })

  it('orders the frame ids ascending', () => {
    for (let i = 1; i < table.frameIds.length; i++) {
      expect(table.frameIds[i]!).toBeGreaterThan(table.frameIds[i - 1]!)
    }
  })
})

describe('filterAll matches Python', () => {
  it('has cases to check', () => {
    expect(fixture.cases.length).toBeGreaterThan(40)
  })

  it.each(fixture.cases.map((c, i) => [i, c.label, c] as const))(
    'case %i: %s',
    (_index, _label, testCase) => {
      const filters: FilterState = {
        numeric: testCase.numeric,
        categorical: testCase.categorical,
        ...(testCase.visible === null ? {} : { visible: testCase.visible })
      }

      const mask = filterAll(table, filters)
      const expected = unpackMask(testCase.kept_bits, table.rows)

      // The count first, because a count mismatch is the readable failure;
      // the rows after, because a count alone would pass a filter that kept
      // the right number of the wrong ones.
      const kept = mask.reduce((total, bit) => total + bit, 0)
      expect(kept).toBe(testCase.kept_count)

      const differing: number[] = []
      for (let row = 0; row < table.rows; row++) {
        if (mask[row] !== expected[row]) {
          differing.push(row)
        }
      }
      expect(differing.slice(0, 10)).toEqual([])
    }
  )
})

describe('frameRows', () => {
  it('returns a contiguous slice per frame', () => {
    const rows = frameRows(table, 0)
    expect(rows.length).toBeGreaterThan(0)
    const frameColumn = table.columns.get('Frame')
    if (frameColumn?.kind !== 'number') {
      throw new Error('Frame column is not numeric')
    }
    // Every row of position 0 carries the first frame id.
    for (const row of rows) {
      expect(frameColumn.values[row]).toBe(table.frameIds[0])
    }
  })

  it('covers every row across all positions', () => {
    let total = 0
    for (let i = 0; i < table.frameIds.length; i++) {
      total += frameRows(table, i).length
    }
    expect(total).toBe(table.rows)
  })

  it('returns nothing for a position past the end', () => {
    expect(frameRows(table, table.frameIds.length).length).toBe(0)
    expect(frameRows(table, -1).length).toBe(0)
  })
})

describe('visibleRows', () => {
  it('intersects a frame with a mask, in frame order', () => {
    const mask = filterAll(table, { numeric: [], categorical: [], visible: ['visible'] })
    const rows = visibleRows(table, 3, mask)
    const all = frameRows(table, 3)

    expect(rows.length).toBeLessThanOrEqual(all.length)
    for (const row of rows) {
      expect(mask[row]).toBe(1)
    }
    // Order is the frame's own, not ascending row index.
    expect(Array.from(rows)).toEqual(Array.from(all).filter((row) => mask[row] === 1))
  })
})

describe('clampFrameIndex', () => {
  it('returns null when there are no frames', () => {
    expect(clampFrameIndex(0, 5)).toBeNull()
  })

  it('clamps a stale position to the last frame', () => {
    expect(clampFrameIndex(10, 99)).toBe(9)
  })

  it('clamps a negative position to the first', () => {
    expect(clampFrameIndex(10, -3)).toBe(0)
  })

  it('treats a missing position as the first frame', () => {
    expect(clampFrameIndex(10, null)).toBe(0)
  })
})

describe('rangeOf', () => {
  it('ignores non-finite values', () => {
    const [min, max] = rangeOf(table, 'X')
    expect(Number.isFinite(min)).toBe(true)
    expect(Number.isFinite(max)).toBe(true)
    expect(min).toBeLessThanOrEqual(max)
  })

  it('degenerates rather than raising on a column with no finite value', () => {
    // numpy's nanmin raises on an all-NaN column and the Python guarded
    // against it; a column of nothing gets a degenerate range instead of
    // taking the load down.
    const empty = buildTable(
      3,
      [
        { name: 'Frame', kind: 'number', values: Float64Array.from([0, 0, 0]) },
        { name: 'Nothing', kind: 'number', values: Float64Array.from([NaN, NaN, NaN]) }
      ],
      'Frame'
    )
    expect(rangeOf(empty, 'Nothing')).toEqual([0, 0])
  })

  it('returns a degenerate range for an unknown column', () => {
    expect(rangeOf(table, 'NotAColumn')).toEqual([0, 0])
  })
})

describe('rangeOf with a mask', () => {
  it('only counts the rows the mask keeps', () => {
    const table = buildTable(
      4,
      [
        { name: 'Frame', kind: 'number', values: Float64Array.from([0, 0, 1, 1]) },
        { name: 'V', kind: 'number', values: Float64Array.from([-50, 2, 7, 25]) }
      ],
      'Frame'
    )
    expect(rangeOf(table, 'V')).toEqual([-50, 25])
    expect(rangeOf(table, 'V', Uint8Array.from([0, 1, 1, 0]))).toEqual([2, 7])
  })
})
